// Initialize probe timestamp and configuration
const targetUrl = $env.MONITORED_APP_URL || 'https://api.realworld.show/api/tags';
const targetName = 'RealWorld Conduit Platform (Production)';

return [{
  json: {
    targetUrl,
    targetName,
    probeStartTime: Date.now(),
    probeTimestamp: new Date().toISOString()
  }
}];

// Measure latency and evaluate HTTP status
const initData = $('Initialize Probe Configuration').first().json;
const pingResponse = $input.first().json;
const latencyMs = Date.now() - initData.probeStartTime;

// Check status code: HTTP Request node returns statusCode in metadata or response
const statusCode = pingResponse.statusCode || (pingResponse.error ? (pingResponse.error.statusCode || 500) : 200);
const isHealthy = statusCode === 200;

return [{
  json: {
    ...initData,
    primaryStatusCode: statusCode,
    latencyMs: latencyMs,
    isHealthy: isHealthy,
    rawResponse: pingResponse.error ? pingResponse.error.message : 'OK'
  }
}];

// Log healthy heartbeat metric
const data = $input.first().json;
console.log(`[PulseQA Heartbeat] Target: ${data.targetName} | Status: 200 OK | Latency: ${data.latencyMs}ms | Time: ${data.probeTimestamp}`);

return [{
  json: {
    status: 'HEALTHY',
    target: data.targetName,
    url: data.targetUrl,
    latency: `${data.latencyMs}ms`,
    timestamp: data.probeTimestamp
  }
}];

// Process retry outcome and confirm outage
const primaryData = $('Calculate Latency & Health Check').first().json;
const retryResponse = $input.first().json;

const retryStatusCode = retryResponse.statusCode || (retryResponse.error ? (retryResponse.error.statusCode || 500) : 200);
const outageConfirmed = retryStatusCode !== 200;

return [{
  json: {
    ...primaryData,
    retryStatusCode: retryStatusCode,
    outageConfirmed: outageConfirmed,
    retryTimestamp: new Date().toISOString()
  }
}];

// Format Critical Outage Incident Alert
const data = $input.first().json;

const discordPayload = {
  content: "🚨 **@here CRITICAL ALERT: WEB APPLICATION OUTAGE DETECTED**",
  username: "PulseQA Uptime Sentinel",
  avatar_url: "https://cdn-icons-png.flaticon.com/512/564/564619.png",
  embeds: [
    {
      title: "🚨 SERVICE DISRUPTION: Monitored Application Unhealthy",
      description: `Continuous monitoring detected an active outage on **${data.targetName}**.\nBoth the primary probe and the 5-second confirmation retry failed.`,
      color: 15158332, // #E74C3C Red
      fields: [
        {
          name: "Monitored Target",
          value: `[${data.targetName}](${data.targetUrl})\n\`${data.targetUrl}\``,
          inline: false
        },
        {
          name: "Primary Probe Status",
          value: `HTTP \`${data.primaryStatusCode}\` (Latency: ${data.latencyMs}ms)`,
          inline: true
        },
        {
          name: "Retry Probe Status",
          value: `HTTP \`${data.retryStatusCode}\``,
          inline: true
        },
        {
          name: "Incident Timestamp",
          value: `\`${data.retryTimestamp}\``,
          inline: true
        },
        {
          name: "Automated Root-Cause Diagnostic",
          value: data.primaryStatusCode === 530 ? "⚠️ **Cloudflare 530 Error 1016:** Origin DNS failure. Domain DNS or CNAME record points to unreachable host." :
                 data.primaryStatusCode === 404 ? "⚠️ **HTTP 404:** Upstream resource or S3 hosting bucket missing." :
                 "⚠️ **Server Failure:** Upstream server returned 5xx error or connection timed out.",
          inline: false
        },
        {
          name: "Immediate Action Checklist",
          value: "1. Check cloud hosting / DNS dashboard\n2. Verify origin container health & Nginx logs\n3. Confirm SSL certificate validity",
          inline: false
        }
      ],
      footer: {
        text: "PulseQA Uptime Sentinel · Automated Incident Management via n8n"
      }
    }
  ]
};

return [{ json: { ...data, discordPayload } }];

// Format Transient Flap Recovery Notice
const data = $input.first().json;

const discordPayload = {
  username: "PulseQA Uptime Sentinel",
  avatar_url: "https://cdn-icons-png.flaticon.com/512/1006/1006771.png",
  embeds: [
    {
      title: "⚠️ Transient Network Glitch Resolved (Self-Healed)",
      description: `Primary health check returned HTTP \`${data.primaryStatusCode}\`, but the 5-second confirmation retry responded **200 OK**.\nNo active outage confirmed. Service is operating normally.`,
      color: 16776960, // #FFFF00 Yellow
      fields: [
        {
          name: "Target",
          value: data.targetName,
          inline: true
        },
        {
          name: "Recovery Latency",
          value: `${data.latencyMs}ms`,
          inline: true
        }
      ],
      footer: {
        text: `PulseQA Telemetry Sentinel · ${data.retryTimestamp}`
      }
    }
  ]
};

return [{ json: { ...data, discordPayload } }];
